using Microsoft.EntityFrameworkCore;

namespace Shop.Data;

public sealed class ShopDbContext(DbContextOptions<ShopDbContext> options) : DbContext(options)
{
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OrderLine> OrderLines => Set<OrderLine>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<OrderLine>()
            .HasOne(l => l.Order)
            .WithMany(o => o.Lines)
            .HasForeignKey(l => l.OrderId)
            .IsRequired();
    }
}

using Microsoft.EntityFrameworkCore;
using Shop.Data;

namespace Shop.Reports;

public sealed class MonthlyReport(ShopDbContext db)
{
    public Task<List<Order>> LoadAsync(DateOnly month, CancellationToken ct) =>
        db.Orders
            .Include(o => o.Lines)
            .Where(o => o.PlacedOn.Year == month.Year && o.PlacedOn.Month == month.Month)
            .OrderBy(o => o.PlacedOn)
            .ToListAsync(ct);
}

